-- INSPECTION-ONLY UNREGISTERED DRAFT: no personal selectors or dispositions.
-- Requires the reviewed 40-migration chain and both observation drafts.
-- Existing retention effects remain blocked while any mapping is unresolved.
BEGIN;
SET LOCAL search_path=pg_catalog,pg_temp;
SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='60s';
DO $install$
DECLARE r record;body text;next_body text;anchor text;replacement text;
BEGIN
 PERFORM private._collect_fence_require_operator();
 IF current_user<>'postgres' OR session_user<>'postgres'
  OR NOT EXISTS(SELECT 1 FROM private.collect_fence_control WHERE singleton AND mode='fenced')
  OR EXISTS(SELECT 1 FROM private.collect_fence_control WHERE mode<>'fenced') THEN
  RAISE EXCEPTION 'burimunsi_retention_inspection_precondition' USING ERRCODE='55000';END IF;
 FOR r IN SELECT * FROM (VALUES
  ('private._retention_manifest_catalog_v2()','ed1116ec31522c5fb441845df44be82a2499f80e7ad3c8880282da065c0c3215',false,'i',ARRAY['search_path=pg_catalog, pg_temp']::text[],'sql','{postgres=X/postgres}'),
  ('private._retention_manifest_rows_v2(text)','9ca69d5be8080b8813324306e76cda9d342faa83535dcbae23719af287657a0c',true,'s',ARRAY['search_path=app, pg_catalog, pg_temp']::text[],'plpgsql','{postgres=X/postgres}'),
  ('private.retention_capture_inventory_v2(uuid,text,bigint,text,integer)','832b2408f9655d3b29ae3373b072bbc5a5ff5edcd48de5b6b55d014d1dd772ef',true,'v',ARRAY['search_path=pg_catalog, pg_temp']::text[],'plpgsql','{postgres=X/postgres,collect_runtime=X/postgres}')
 ) e(sig,hash,definer,volatility,config,language,acl) LOOP
  IF to_regprocedure(r.sig) IS NULL OR NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(r.sig)
    AND pg_get_userbyid(p.proowner)='postgres' AND p.prosecdef=r.definer AND p.provolatile=r.volatility
    AND p.prokind='f' AND p.proparallel='u' AND NOT p.proleakproof AND l.lanname=r.language AND p.proacl::text=r.acl
    AND p.proconfig=r.config AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')=r.hash) THEN
   RAISE EXCEPTION 'burimunsi_retention_inspection_predecessor_changed' USING ERRCODE='55000';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['burimunsi_accounts','burimunsi_audit','burimunsi_command_receipts','burimunsi_device_accounts','burimunsi_device_grants','burimunsi_detection_profiles','burimunsi_email_preauth','burimunsi_email_preauth_limits','burimunsi_gateway_handoffs','burimunsi_gateway_pair_targets','burimunsi_gateway_retirements','burimunsi_identity_proofs','burimunsi_integration_policies','burimunsi_native_staff_delegations','burimunsi_observation_consents','burimunsi_observation_requests','burimunsi_operator_approvals','burimunsi_owner_commands','burimunsi_pin_login_limits','burimunsi_pin_session_links','burimunsi_provisioning_commands','burimunsi_rate_limits','burimunsi_receipt_jobs','burimunsi_rematch_jobs','burimunsi_schedulers','burimunsi_scope_setup_commands','burimunsi_scopes','burimunsi_session_links','burimunsi_sessions','burimunsi_sms_source_scopes','burimunsi_transaction_scopes','burimunsi_unresolved_observations','burimunsi_worker_grants']::text[]) n WHERE NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace p ON p.oid=c.relnamespace WHERE p.nspname='private' AND c.relname=n AND c.relkind='r'))
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(private._retention_manifest_catalog_v2()->'private_classes') e WHERE e->>'relation'=ANY(SELECT 'private.'||n FROM unnest(ARRAY['burimunsi_accounts','burimunsi_audit','burimunsi_command_receipts','burimunsi_device_accounts','burimunsi_device_grants','burimunsi_detection_profiles','burimunsi_email_preauth','burimunsi_email_preauth_limits','burimunsi_gateway_handoffs','burimunsi_gateway_pair_targets','burimunsi_gateway_retirements','burimunsi_identity_proofs','burimunsi_integration_policies','burimunsi_native_staff_delegations','burimunsi_observation_consents','burimunsi_observation_requests','burimunsi_operator_approvals','burimunsi_owner_commands','burimunsi_pin_login_limits','burimunsi_pin_session_links','burimunsi_provisioning_commands','burimunsi_rate_limits','burimunsi_receipt_jobs','burimunsi_rematch_jobs','burimunsi_schedulers','burimunsi_scope_setup_commands','burimunsi_scopes','burimunsi_session_links','burimunsi_sessions','burimunsi_sms_source_scopes','burimunsi_transaction_scopes','burimunsi_unresolved_observations','burimunsi_worker_grants']::text[]) n)) THEN
  RAISE EXCEPTION 'burimunsi_retention_inspection_schema_changed' USING ERRCODE='55000';END IF;
 -- Add exact schema names only. The catalog asserts no subject association.
 SELECT prosrc INTO STRICT body FROM pg_proc WHERE oid='private._retention_manifest_catalog_v2()'::regprocedure;
 next_body:='SELECT jsonb_set(base,''{private_classes}'',(base->''private_classes'')||''[{"name":"private:burimunsi_accounts","relation":"private.burimunsi_accounts","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_audit","relation":"private.burimunsi_audit","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_command_receipts","relation":"private.burimunsi_command_receipts","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_device_accounts","relation":"private.burimunsi_device_accounts","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_device_grants","relation":"private.burimunsi_device_grants","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_detection_profiles","relation":"private.burimunsi_detection_profiles","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_email_preauth","relation":"private.burimunsi_email_preauth","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_email_preauth_limits","relation":"private.burimunsi_email_preauth_limits","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_gateway_handoffs","relation":"private.burimunsi_gateway_handoffs","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_gateway_pair_targets","relation":"private.burimunsi_gateway_pair_targets","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_gateway_retirements","relation":"private.burimunsi_gateway_retirements","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_identity_proofs","relation":"private.burimunsi_identity_proofs","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_integration_policies","relation":"private.burimunsi_integration_policies","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_native_staff_delegations","relation":"private.burimunsi_native_staff_delegations","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_observation_consents","relation":"private.burimunsi_observation_consents","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_observation_requests","relation":"private.burimunsi_observation_requests","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_operator_approvals","relation":"private.burimunsi_operator_approvals","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_owner_commands","relation":"private.burimunsi_owner_commands","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_pin_login_limits","relation":"private.burimunsi_pin_login_limits","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_pin_session_links","relation":"private.burimunsi_pin_session_links","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_provisioning_commands","relation":"private.burimunsi_provisioning_commands","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_rate_limits","relation":"private.burimunsi_rate_limits","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_receipt_jobs","relation":"private.burimunsi_receipt_jobs","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_rematch_jobs","relation":"private.burimunsi_rematch_jobs","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_schedulers","relation":"private.burimunsi_schedulers","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_scope_setup_commands","relation":"private.burimunsi_scope_setup_commands","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_scopes","relation":"private.burimunsi_scopes","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_session_links","relation":"private.burimunsi_session_links","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_sessions","relation":"private.burimunsi_sessions","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_sms_source_scopes","relation":"private.burimunsi_sms_source_scopes","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_transaction_scopes","relation":"private.burimunsi_transaction_scopes","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_unresolved_observations","relation":"private.burimunsi_unresolved_observations","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true},{"name":"private:burimunsi_worker_grants","relation":"private.burimunsi_worker_grants","scope":"unmapped_private","purpose":"Unreviewed subject mapping and object custody; inspection only, effects blocked","blocked":true}]''::jsonb) FROM ('||body||') prior(base)';
 EXECUTE 'CREATE OR REPLACE FUNCTION private._retention_manifest_catalog_v2() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS '||quote_literal(next_body);
 -- Suppress partial subject/object projections. A null count and unresolved
 -- lifecycle are stronger than treating missing observation keys as zero.
 SELECT prosrc INTO STRICT body FROM pg_proc WHERE oid='private._retention_manifest_rows_v2(text)'::regprocedure;
 anchor:=$a$  IF coalesce((c->>'blocked')::boolean,false) THEN$a$;
 replacement:=$b$  IF c->>'scope'='unmapped_private' OR c->>'name'=ANY(ARRAY['private:storage_payload_reservations','private:storage_put_intents','private:storage_upload_attempts','private:storage_objects','private:storage_delete_intents','private:object_metadata']::text[]) THEN
   RETURN QUERY SELECT c->>'name',jsonb_build_object('kind','class','status','unmapped','subject_count',NULL,
    'erasure','blocked','present',to_regclass(c->>'relation') IS NOT NULL,'object_custody','unverified',
    'lifecycle',jsonb_build_object('unresolved',true));
   CONTINUE;
  END IF;
  IF coalesce((c->>'blocked')::boolean,false) THEN$b$;
 IF length(body)-length(replace(body,anchor,''))<>length(anchor) THEN RAISE EXCEPTION 'burimunsi_retention_inspection_anchor_changed' USING ERRCODE='55000';END IF;
 next_body:=replace(body,anchor,replacement);
 anchor:=$a$ RETURN QUERY SELECT * FROM private._retention_manifest_managed_rows_v2(p_subject,(1000001-produced)::integer);$a$;
 replacement:=$b$ RETURN QUERY SELECT managed.class_name,CASE WHEN managed.class_name='managed:storage' THEN
  jsonb_build_object('kind','class','status','unmapped','subject_count',NULL,'erasure','blocked',
   'object_custody','unverified','lifecycle',jsonb_build_object('unresolved',true)) ELSE managed.descriptor END
 FROM private._retention_manifest_managed_rows_v2(p_subject,(1000001-produced)::integer) managed
 WHERE managed.class_name<>'managed:storage' OR managed.descriptor->>'kind'='class';$b$;
 IF length(next_body)-length(replace(next_body,anchor,''))<>length(anchor) THEN RAISE EXCEPTION 'burimunsi_retention_inspection_anchor_changed' USING ERRCODE='55000';END IF;
 next_body:=replace(next_body,anchor,replacement);
 EXECUTE 'CREATE OR REPLACE FUNCTION private._retention_manifest_rows_v2(p_subject text) RETURNS TABLE(class_name text,descriptor jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=app,pg_catalog,pg_temp AS '||quote_literal(next_body);
 -- Aggregate row counts for these classes are explicitly null, not zero.
 SELECT prosrc INTO STRICT body FROM pg_proc WHERE oid='private.retention_capture_inventory_v2(uuid,text,bigint,text,integer)'::regprocedure;
 anchor:=$a$'descriptor_count',n,'rows',row_count,'status',status$a$;
 replacement:=$b$'descriptor_count',n,'rows',CASE WHEN class_name=ANY(ARRAY['private:burimunsi_accounts','private:burimunsi_audit','private:burimunsi_command_receipts','private:burimunsi_device_accounts','private:burimunsi_device_grants','private:burimunsi_detection_profiles','private:burimunsi_email_preauth','private:burimunsi_email_preauth_limits','private:burimunsi_gateway_handoffs','private:burimunsi_gateway_pair_targets','private:burimunsi_gateway_retirements','private:burimunsi_identity_proofs','private:burimunsi_integration_policies','private:burimunsi_native_staff_delegations','private:burimunsi_observation_consents','private:burimunsi_observation_requests','private:burimunsi_operator_approvals','private:burimunsi_owner_commands','private:burimunsi_pin_login_limits','private:burimunsi_pin_session_links','private:burimunsi_provisioning_commands','private:burimunsi_rate_limits','private:burimunsi_receipt_jobs','private:burimunsi_rematch_jobs','private:burimunsi_schedulers','private:burimunsi_scope_setup_commands','private:burimunsi_scopes','private:burimunsi_session_links','private:burimunsi_sessions','private:burimunsi_sms_source_scopes','private:burimunsi_transaction_scopes','private:burimunsi_unresolved_observations','private:burimunsi_worker_grants','private:storage_payload_reservations','private:storage_put_intents','private:storage_upload_attempts','private:storage_objects','private:storage_delete_intents','private:object_metadata','managed:storage','r2:sms_receipts']::text[]) THEN NULL ELSE row_count END,'status',status$b$;
 IF length(body)-length(replace(body,anchor,''))<>length(anchor) THEN RAISE EXCEPTION 'burimunsi_retention_inspection_anchor_changed' USING ERRCODE='55000';END IF;
 next_body:=replace(body,anchor,replacement);
 EXECUTE 'CREATE OR REPLACE FUNCTION private.retention_capture_inventory_v2(p_operation uuid,p_request text,p_review bigint,p_source text,p_max_rows integer DEFAULT 1000000) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS '||quote_literal(next_body);
END;$install$;
COMMIT;
